package com.dvopenlabs.freedom.companions;

import android.app.*;
import android.os.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Private configuration and foreground-only controls. Nothing connects until explicitly saved. */
public final class HubActivity extends Activity {
    LinearLayout page;final Handler main=new Handler(Looper.getMainLooper());ExecutorService worker;
    boolean visible;String screen="home";int generation;
    final Runnable poll=new Runnable(){public void run(){if(visible&&"home".equals(screen)){loadHome(false);main.postDelayed(this,10000);}}};
    int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
    TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xfff3f6fc);t.setTextSize(size);t.setTypeface(getResources().getFont(R.font.outfit));t.setFontVariationSettings(size>=26?"'wght' 550":"'wght' 400");t.setPadding(0,dp(6),0,dp(8));return t;}
    void start(String title,String intro){if("home".equals(screen))getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);else getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);generation++;page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(40),dp(28),dp(40),dp(32));page.addView(text(title,28));page.addView(text(intro,17));ScrollView scroll=new ScrollView(this);scroll.addView(page);setContentView(scroll);}
    void button(String label,Runnable action){TextView b=text(label,19);b.setPadding(dp(18),dp(16),dp(18),dp(16));b.setFocusable(true);b.setFocusableInTouchMode(true);b.setClickable(true);b.setBackgroundResource(R.drawable.freedom_action);b.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[0]},new int[]{0xff182334,0xfff3f6fc}));b.setOnClickListener(v->action.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(8);page.addView(b,lp);if(page.getChildCount()==3)b.requestFocus();}
    EditText field(String hint,String value,boolean secret){page.addView(text(hint,16));EditText e=new EditText(this);e.setTextColor(-1);e.setHintTextColor(0xffa8bdcf);e.setText(value);e.setHint(hint);e.setSingleLine(true);e.setTextSize(18);e.setInputType(secret?InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD:InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);e.setImportantForAutofill(View.IMPORTANT_FOR_AUTOFILL_NO);page.addView(e,new LinearLayout.LayoutParams(-1,dp(58)));return e;}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);}
    @Override public void onResume(){super.onResume();visible=true;worker=Executors.newSingleThreadExecutor();home();main.postDelayed(poll,10000);}
    @Override public void onPause(){visible=false;generation++;main.removeCallbacksAndMessages(null);if(worker!=null)worker.shutdownNow();super.onPause();}
    void home(){screen="home";start("Your home, at a glance","Optional connections stay on this TV. Home Assistant and calendar feeds are unconfigured until you add them.");button("Home Assistant · connection & favorites",this::configureHome);button("Family calendar & Game Day",this::calendar);button("Poster artwork & privacy",this::privacy);button("Discover & watchlist",()->startActivity(new android.content.Intent(this,DiscoverActivity.class)));button("Photo & Art appearance",()->startActivity(new android.content.Intent(this,AmbientSettingsActivity.class)));button("Museum art",()->startActivity(new android.content.Intent(this,ArtGalleryActivity.class)));button("Personal photo sources",()->startActivity(new android.content.Intent(this,PhotoSourcesActivity.class)));loadHome(true);}
    void configureHome(){screen="config";var p=HubStore.prefs(this);start("Connect Home Assistant","Use your server address and a long-lived access token. Local HTTP is unencrypted; use only on a trusted network. Tokens never appear in snapshots or logs.");EditText address=field("https://your-home-assistant",p.getString("ha",""),false),token=field("Access token",p.getString("token",""),true);button("Save connection",()->{try{String url=address.getText().toString().trim();Network.url(url,true);String secret=token.getText().toString().trim();if(secret.isEmpty()||secret.length()>8192||secret.contains("\n")||secret.contains("\r"))throw new IllegalArgumentException();HubStore.prefs(this).edit().putString("ha",url.replaceAll("/+$","")).putString("token",secret).remove("favorites").apply();favorites();}catch(Exception invalid){Toast.makeText(this,"Check the server address and token",Toast.LENGTH_LONG).show();}});button("Choose favorites",this::favorites);button("Disconnect and forget token",()->{p.edit().remove("ha").remove("token").remove("favorites").apply();home();});button("Cancel",this::home);}
    void calendar(){screen="calendar";var p=HubStore.prefs(this);start("Family calendar & Game Day","Add read-only HTTPS iCalendar subscription links. They can contain secrets: keep them private. Refreshes at most twice daily while a panel is open; no background service or live scores.");EditText family=field("Family calendar HTTPS link",p.getString("family",""),true),sports=field("Sports calendar HTTPS link",p.getString("sports",""),true);CheckBox share=new CheckBox(this);share.setText("Enable calendar and share next events with DV Freedom Home");share.setTextColor(-1);share.setChecked(p.getBoolean("calendar",false));page.addView(share);button("Apply feeds & sharing",()->{try{String f=family.getText().toString().trim(),s=sports.getText().toString().trim();if(!f.isEmpty())Network.url(f,false);if(!s.isEmpty())Network.url(s,false);p.edit().putString("family",f).putString("sports",s).putBoolean("calendar",share.isChecked()&&(!f.isEmpty()||!s.isEmpty())).remove("events").remove("updated").remove("attempt").apply();HubStore.refresh(this);getContentResolver().notifyChange(HubStore.URI,null);showEvents();}catch(Exception bad){Toast.makeText(this,"Use public HTTPS calendar links without redirects",Toast.LENGTH_LONG).show();}});button("View upcoming events",this::showEvents);button("Forget feeds and cached events",()->{p.edit().remove("family").remove("sports").remove("events").remove("updated").remove("attempt").putBoolean("calendar",false).apply();getContentResolver().notifyChange(HubStore.URI,null);calendar();});button("Cancel",this::home);}
    void showEvents(){screen="events";start("Coming up","Family events and sports countdowns · cached on this TV");HubStore.refresh(this);JSONArray events=HubStore.events(this);List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<events.length();i++)if(events.optJSONObject(i)!=null&&events.optJSONObject(i).optLong("at")>System.currentTimeMillis()-86400000)sorted.add(events.optJSONObject(i));sorted.sort(Comparator.comparingLong(x->x.optLong("at")));for(JSONObject e:sorted.subList(0,Math.min(12,sorted.size()))){long days=Math.max(0,(e.optLong("at")-System.currentTimeMillis())/86400000);page.addView(text(e.optString("title")+"\n"+e.optString("source")+" · "+(e.optBoolean("allDay")?"All day · ":"")+java.text.DateFormat.getDateTimeInstance().format(new Date(e.optLong("at")))+" · "+EventDisplay.countdown(e.optLong("at"),System.currentTimeMillis(),e.optBoolean("allDay"),java.time.ZoneId.systemDefault()),19));}if(sorted.isEmpty())page.addView(text("No upcoming events cached. Add a feed or return after the first refresh.",18));long updated=HubStore.prefs(this).getLong("updated",0);page.addView(text(updated==0?"Not refreshed yet":"Last refreshed "+java.text.DateFormat.getDateTimeInstance().format(new Date(updated))+(HubStore.prefs(this).getBoolean("failed",false)?" · Refresh unavailable; showing saved events":""),15));button("Reload cached events",this::showEvents);button("Back",this::home);}
    void privacy(){screen="privacy";var p=HubStore.prefs(this);start("Artwork & privacy","Optional HTTPS poster downloads come from URLs shared by your streaming apps. Their hosts receive your IP and request. No credentials are sent. Cache is bounded to 16 MB; local artwork works with this off.");CheckBox enable=new CheckBox(this);enable.setText("Allow network posters for DV Freedom shelves");enable.setTextColor(-1);enable.setChecked(p.getBoolean("posters",false));page.addView(enable);button("Apply",()->{p.edit().putBoolean("posters",enable.isChecked()).apply();if(!enable.isChecked())HubStore.clear(this);getContentResolver().notifyChange(HubStore.URI,null);home();});button("Clear cached posters and events",()->{HubStore.clear(this);Toast.makeText(this,"Cache cleared",Toast.LENGTH_SHORT).show();});button("Open-source notices",()->{try{String value=readNotices();screen="notices";start("Open-source notices","Companion dependencies and their licenses");page.addView(text(value,14));button("Back",this::privacy);}catch(Exception missing){Toast.makeText(this,"Notices unavailable",Toast.LENGTH_LONG).show();}});button("Cancel",this::home);}
    String readNotices()throws Exception{try(java.io.InputStream in=getAssets().open("third-party-notices.txt");java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1&&out.size()<200000)out.write(b,0,n);return new String(out.toByteArray(),StandardCharsets.UTF_8);}}
    JSONArray states()throws Exception{var p=HubStore.prefs(this);String url=p.getString("ha","");if(url.isEmpty())return new JSONArray();return new JSONArray(new String(Network.request(url+"/api/states",p.getString("token",""),null,true,2*1024*1024),StandardCharsets.UTF_8));}
    static boolean supported(String id){return HomeEntityPolicy.supported(id);}
    void favorites(){screen="favorites";start("Favorite controls","Choose up to eight lights, switches, fans or scenes. Security devices are excluded. No actions run while browsing.");int g=generation;worker.execute(()->{try{JSONArray states=states();main.post(()->{if(!visible||g!=generation)return;Set<String> selected=new HashSet<>(HubStore.prefs(this).getStringSet("favorites",Collections.emptySet()));List<CheckBox> choices=new ArrayList<>();for(int i=0;i<Math.min(states.length(),500);i++){JSONObject e=states.optJSONObject(i);if(e==null||!supported(e.optString("entity_id")))continue;CheckBox box=new CheckBox(this);String id=e.optString("entity_id");box.setTag(id);box.setText(e.optJSONObject("attributes")==null?id:e.optJSONObject("attributes").optString("friendly_name",id));box.setTextColor(-1);box.setChecked(selected.contains(id));page.addView(box);choices.add(box);}button("Save favorites",()->{Set<String> next=new HashSet<>();for(CheckBox b:choices)if(b.isChecked())next.add((String)b.getTag());if(next.size()>8){Toast.makeText(this,"Choose at most eight",Toast.LENGTH_LONG).show();return;}HubStore.prefs(this).edit().putStringSet("favorites",next).apply();home();});button("Cancel",this::home);});}catch(Exception unavailable){main.post(()->{if(visible&&g==generation){page.addView(text("Could not connect. Check your server address, token and network.",18));button("Back",this::configureHome);}});}});}
    void loadHome(boolean first){int g=generation;var p=HubStore.prefs(this);if(p.getString("ha","").isEmpty()){if(first)page.addView(text("Home Assistant is not connected. Add it whenever you’re ready.",18));return;}Set<String> selected=new HashSet<>(p.getStringSet("favorites",Collections.emptySet()));if(selected.isEmpty())return;worker.execute(()->{try{JSONArray states=states();main.post(()->{if(!visible||g!=generation||!"home".equals(screen))return;View focused=getCurrentFocus();Object focusTag=focused==null?null:focused.getTag();for(int i=page.getChildCount()-1;i>=0;i--)if(String.valueOf(page.getChildAt(i).getTag()).startsWith("entity:"))page.removeViewAt(i);for(int i=0;i<states.length();i++){JSONObject e=states.optJSONObject(i);if(e==null)continue;String id=e.optString("entity_id");if(!selected.contains(id)||!supported(id))continue;JSONObject attrs=e.optJSONObject("attributes");String label=HomeEntityPolicy.summary(e);boolean available=!Arrays.asList("unavailable","unknown").contains(e.optString("state"));button(label,()->{if(available&&!HomeEntityPolicy.actionable(id)){new AlertDialog.Builder(this).setTitle("Reported state").setMessage(label+"\nRead-only in this panel.").setPositiveButton("Close",null).show();return;}if(available)new AlertDialog.Builder(this).setTitle("Run this control?").setMessage(label).setPositiveButton("Run",(d,w)->action(id)).setNegativeButton("Cancel",null).show();});View control=page.getChildAt(page.getChildCount()-1);control.setTag("entity:"+id);if(control.getTag().equals(focusTag))control.requestFocus();}});}catch(Exception unavailable){if(first)main.post(()->{if(visible&&g==generation)page.addView(text("Home Assistant unavailable. No controls changed.",18));});}});}
    void action(String id){if(!HomeEntityPolicy.actionable(id))return;int g=generation;worker.execute(()->{boolean ok=false;try{var p=HubStore.prefs(this);String domain=id.substring(0,id.indexOf('.'));Network.request(p.getString("ha","")+"/api/services/"+domain+"/"+(domain.equals("scene")?"turn_on":"toggle"),p.getString("token",""),new JSONObject().put("entity_id",id).toString(),true,65536);ok=true;}catch(Exception ignored){}boolean result=ok;main.post(()->{if(visible&&g==generation){Toast.makeText(this,result?"Control sent":"Control unavailable",Toast.LENGTH_LONG).show();loadHome(false);}});});}
    @Override public void onBackPressed(){if(!"home".equals(screen))home();else super.onBackPressed();}
}
